tinymce.PluginManager.add('tablaturad', function(editor, url) {

    // Add a button that opens a window
    editor.ui.registry.addButton('tablaturad', {
        text: 'Tab D',
        tooltip: 'Inserir Tablatura em Ré',
        onAction: function() {
            // Open window
            editor.insertContent('<p class="tab">&nbsp;<span class="corda">D</span>|-------------------------<br />&nbsp;<span class="corda">A</span>|-------------------------<br /><span class="corda">F#</span>|-------------------------<br />&nbsp;<span class="corda">D</span>|-------------------------<br />&nbsp;<span class="corda">A</span>|-------------------------</p>');

        }
    });

});